22: // Generic RAII guard for resources identified by a sentinel "invalid" value and
23: // a free-function closer.  Non-copyable, non-movable.
24: //
25: // Usage:
26: //   using ScopedFd = ScopedResource<-1, close_fd>;
27: //   ScopedFd guard(fd);          // destructor calls close_fd(fd)
28: //   int raw = guard.release();   // relinquish ownership
29: template <auto Invalid, void (*Close)(decltype(Invalid))>
30: class ScopedResource {
31:   using T = decltype(Invalid);
32:   T val_;
33: 
34:  public:
35:   explicit ScopedResource(T v) : val_(v) {}
36:   ~ScopedResource() {
37:     if (val_ != Invalid) {
38:       Close(val_);
39:     }
40:   }
41:   T get() const {
42:     return val_;
43:   }
44:   T release() {
45:     T tmp = val_;
46:     val_ = Invalid;
47:     return tmp;
48:   }
49:   ScopedResource(const ScopedResource&) = delete;
50:   ScopedResource& operator=(const ScopedResource&) = delete;
51: };
52: 
53: // Platform-specific type aliases.
54: 
55: #ifdef _WIN32
56: inline void close_handle(HANDLE h) {
57:   CloseHandle(h);
58: }
59: using ScopedHandle = ScopedResource<INVALID_HANDLE_VALUE, close_handle>;
60: #endif
61: 
62: inline void close_fd(int fd) {
63: #ifdef _WIN32
64:   _close(fd);
65: #else
66:   close(fd);
67: #endif
68: }
69: using ScopedFd = ScopedResource<-1, close_fd>;
70: 
71: // RAII guard that invokes a callable on destruction (scope exit).
72: template <typename F>
73: class ScopeExit {
74:   F fn_;
75: 
76:  public:
77:   explicit ScopeExit(F fn) : fn_(std::move(fn)) {}
78:   ~ScopeExit() noexcept {
79:     static_assert(std::is_nothrow_invocable_v<F&>, "ScopeExit callable must be noexcept");
80:     fn_();
81:   }
82:   ScopeExit(const ScopeExit&) = delete;
83:   ScopeExit& operator=(const ScopeExit&) = delete;
84: };
